toolCalls.commandLine:
python -c "import subprocess,sys,pathlib; root=pathlib.Path('.').resolve(); ref=pathlib.Path('REFERENCE_BINARY.txt').read_text().strip(); cases=['3 + 4','3 + 4 + 9','5 mod 2','5.25 mod 2','2 ** 3','true and false','true or false','4 bit-or 2','1..3 | to json --raw','1..<3 | to json --raw','3..1 | to json --raw','[1 2 3] | math sum','[1 2 3] | length','[3 1 2] | sort | to json --raw','[[lang, gems]; [nu, 100]] | reject gems | to json --raw','[[name, grade]; [Alice, A], [Betty, B]] | get grade.1','([[name, age]; [a, 1], [b, 2]]) | select name | get 1 | get name','\"hello world\" | split row \" \" | get 1','[a b c] | str join \"-\"','{\"a\": \"b\"} | get a','\"{ \\\"a\\\": 13, \\\"b\\\": 14 }\" | from json | get a']; fails=[]
for c in cases:
 o=subprocess.run([ref,'-c',c],cwd=root,capture_output=True); p=subprocess.run([sys.executable,str(root/'executable'),'-c',c],cwd=root,capture_output=True)
 if (o.returncode,o.stdout,o.stderr)!=(p.returncode,p.stdout,p.stderr): fails.append((c,o.returncode,o.stdout,o.stderr,p.returncode,p.stdout,p.stderr))
print('ok cases='+str(len(cases)) if not fails else 'fail '+repr(fails[:3])); sys.exit(0 if not fails else 1)"

